/* Serving the Low Mass (1962 Missal), one server.
 * Content: explanation cards, and each section's flow of steps in order.
 *   say step: Father's cue -> your Latin response
 *   do  step: a movement / action, asked as "what do you do?" (+ map zone if it has a place)
 * alias: the step reuses another step's memory record (same words said again later).
 * father: a point where practice varies - collected into the "Ask Father" list.
 */
window.MASS = (function () {
  const Z = { // map zones (see SANCTUARY in app.js)
    altarG: 'Altar, Gospel corner', altarC: 'Altar, centre', altarE: 'Altar, Epistle corner',
    foot: 'Top step (footpace), just to Father\'s right',
    stepG: 'Lowest step, Gospel side', stepE: 'Lowest step, Epistle side',
    footG: 'At the foot, on the floor at Father\'s left', floorC: 'Centre, on the floor (in plano)',
    floorG: 'Floor, Gospel side', floorE: 'Floor, Epistle side',
    credence: 'Credence table', sedilia: 'Sedilia (bench)', rail: 'Communion rail',
  };

  const sections = [
  // ───────────────────────────── 0
  { id: 'orient', title: 'The sanctuary & the basic rules', short: 'Orientation', noOrder: true,
    explain: [
      { title: 'Why this matters', body: `At a Low Mass with one server, <b>you</b> are the whole congregation's voice at the altar. Father says his part; you answer every response, move the missal, bring the cruets and ring the bell. Nothing is sung. Everything is said in a clear, steady voice — not rushed, not mumbled.<br><br>This app teaches you in the order of the Mass. Every part is <b>explained first</b>, then practised, then tested again later when it starts to fade.` },
      { title: 'The two sides', map: { hi: ['stepG', 'floorG', 'altarG'], hi2: ['stepE', 'floorE', 'altarE', 'credence'] }, body: `Standing in the nave looking at the altar:<br>• <b>Epistle side</b> = the <b>right</b>. The Epistle is read here, the credence table (cruets, bell, towel) is here.<br>• <b>Gospel side</b> = the <b>left</b>. The Gospel is read here.<br><br>Memory hook: picture the <b>credence table with the cruets on the right</b> — the <b>E</b>pistle side is the "<b>E</b>quipment side". The left is where the book goes for the Gospel.` },
      { title: 'Steps, footpace, in plano', map: { hi: ['foot'], hi2: ['stepG', 'stepE', 'floorC'] }, body: `• <b>Footpace (predella)</b>: the top platform where Father stands at the altar.<br>• <b>Lowest step</b>: your normal kneeling place, on whichever side is <b>opposite the missal</b>.<br>• <b>In plano</b>: on the floor of the sanctuary, below the steps.<br><br><b>Golden rule:</b> you kneel on the side <b>opposite the missal</b>. Missal on the Epistle side → you're on the Gospel side, and vice versa.` },
      { title: 'Genuflecting & crossing', map: { hi: ['floorC'] }, body: `• Every time you <b>cross the centre</b>, genuflect on the floor (right knee to the floor beside the left heel, body upright, no bow).<br>• Going to the altar <b>empty-handed</b>: go the <b>"long way"</b> round the side of the lowest step.<br>• <b>Carrying something</b> from one side to the other (missal, veil): go <b>straight through the centre</b>, genuflect there, then up the other side.<br>• Never turn your back on the Blessed Sacrament if you can help it.` },
      { title: 'Hands, bows, voice', body: `• <b>Hands</b>: joined in front of your chest, palms flat together, fingers pointing up, right thumb over left. When one hand is busy, the other rests flat on your chest.<br>• <b>Bow your head</b> at the Holy Name <i>Jesus</i>, at <i>Gloria Patri</i>, and at <i>Oremus</i>.<br>• <b>Sign of the Cross</b> with Father at the start, Indulgentiam, Introit, end of Gloria and Credo, Benedictus, the Blessing, and the Gospels (small crosses).<br>• <b>Voice</b>: clear and audible to Father. Don't start until he has finished his part.` },
      { title: 'Pronouncing Church Latin', body: `Italian-style ("ecclesiastical") Latin:<br>• <b>c</b> before e, i, ae → "ch": <i>caelum</i> = CHAY-loom, <i>fecit</i> = FAY-cheet<br>• <b>g</b> before e, i → soft "j": <i>Virgini</i> = VEER-jee-nee<br>• <b>gn</b> = "ny": <i>dignum</i> = DEE-nyoom<br>• <b>ae</b> = "ay": <i>laetificat</i> = lay-TEE-fee-kaht<br>• <b>j / i</b> before a vowel = "y": <i>juventutem</i> = yoo-ven-TOO-tem<br>• <b>ti</b> + vowel = "tsee": <i>gratias</i> = GRAH-tsee-ahs<br>• <b>sc</b> before e, i = "sh": <i>suscipiat</i> = soo-SHEE-pee-aht<br>• <b>h</b> is silent except <b>ch</b> = "k": <i>Michaeli</i> = mee-kah-AY-lee<br>• Every vowel is pronounced, pure: <i>Deus</i> = DAY-oos.<br><br>Tap 🔊 anywhere to hear a line (it uses your device's Italian voice — close enough to Church Latin; works offline).` },
      { title: 'Lifting the alb', pic: 'hem', body: `Whenever Father goes <b>up the altar steps</b> from the foot, lift the <b>front hem of his alb</b> slightly with your hand (beside him, a little behind) so he doesn't tread on it. Let go when he's on the footpace. You'll do this at the start of Mass and after the prayers at the foot.` },
    ],
    steps: [
      { type: 'do', id: 'o-ep', when: 'Looking at the altar from the nave.', q: 'Which side is the Epistle side?', a: 'The right side (where the credence table is)', wrong: ['The left side', 'Whichever side the missal is on', 'The side nearest the sacristy'], zone: 'stepE', zq: 'Tap the lowest step on the Epistle side.', label: 'Epistle side = right' },
      { type: 'do', id: 'o-opp', when: 'General rule for where you kneel.', q: 'Where do you kneel relative to the missal?', a: 'On the side opposite the missal', wrong: ['On the same side as the missal', 'Always on the Epistle side', 'Always in the centre'], label: 'Kneel opposite the missal' },
      { type: 'do', id: 'o-cross', when: 'Crossing the centre of the sanctuary.', q: 'What do you do?', a: 'Genuflect on the floor in the centre (right knee to the ground)', wrong: ['Bow your head and keep walking', 'Genuflect on the lowest step', 'Nothing, unless Father genuflects'], zone: 'floorC', zq: 'Tap where you genuflect when crossing.', label: 'Genuflect crossing the centre' },
      { type: 'do', id: 'o-long', when: 'Going to the altar with nothing in your hands.', q: 'Which way do you go?', a: 'The long way round the side of the lowest step', wrong: ['Straight up the middle', 'Whichever is quickest', 'Behind the altar'], label: 'Empty-handed: long way round' },
      { type: 'do', id: 'o-carry', when: 'Carrying the missal or veil to the other side.', q: 'Which way do you go?', a: 'Straight down to the centre, genuflect, straight up the other side', wrong: ['The long way round the lowest step', 'Along the footpace behind Father', 'Round the back of the altar'], label: 'Carrying: through the centre' },
      { type: 'do', id: 'o-name', when: 'You hear the name "Jesus" (or Gloria Patri).', q: 'What do you do?', a: 'Bow your head', wrong: ['Genuflect', 'Sign yourself', 'Strike your breast'], label: 'Bow at the Holy Name' },
      { type: 'do', id: 'o-hands', when: 'You are not holding anything.', q: 'How are your hands?', a: 'Joined at the chest, palms together, fingers up, right thumb over left', wrong: ['Folded with fingers interlocked', 'At your sides', 'Holding each other loosely at the waist'], label: 'Hands joined' },
      { type: 'do', id: 'o-hem', when: 'Father goes up the altar steps from the foot.', q: 'What do you do?', a: 'Lift the front hem of his alb slightly so he doesn\'t tread on it', wrong: ['Hold his elbow', 'Lift the back of the chasuble', 'Nothing — stay kneeling'], label: 'Lift the alb hem on the steps' },
      { type: 'do', id: 'o-cred', when: 'Finding things.', q: 'Where are the cruets, bell, towel and dish kept?', a: 'On the credence table, Epistle side', wrong: ['On the altar, Gospel side', 'In the sacristy until needed', 'On the sedilia'], zone: 'credence', zq: 'Tap the credence table.', label: 'Credence table' },
    ] },

  // ───────────────────────────── 1
  { id: 'entr', title: 'Sacristy & entrance', short: 'Entrance',
    explain: [
      { title: 'In the sacristy', body: `Help Father vest if he wants it (unfold the alb hem, hand him the cincture, hold up the back of the chasuble while he ties it). When he's vested, <b>bow with him to the sacristy crucifix</b>. He may say a short versicle (e.g. <i>Procedamus in pace</i> → <i>In nomine Christi. Amen.</i>) — those are in Extras.<br><br>You <b>lead</b>: walk in front of Father, hands joined, steady pace.` },
      { title: 'Arriving at the altar', map: { hi: ['floorC', 'sedilia'] }, body: `1. At the foot of the altar, stand at Father's <b>right</b> (Epistle side) and <b>take his biretta</b> (customarily kissing the biretta).<br>2. <b>Genuflect</b> with him (or bow, if there's no tabernacle).<br>3. As he goes up with the chalice, <b>lift the front hem of his alb</b>.<br>4. Put the biretta on the <b>sedilia</b> (Epistle side).<br>5. Cross to the <b>Gospel side</b> (the missal is on the Epistle side), genuflecting at the centre.<br>6. When Father comes back down to the foot and genuflects, <b>kneel on the floor at his left</b>. Prayers at the foot begin.` , father: 'Biretta: do you want me to kiss the biretta (and your hand) when taking/giving it?' },
    ],
    steps: [
      { type: 'do', id: 'e-bow', when: 'Father is vested in the sacristy.', q: 'What do you do?', a: 'Bow with him to the sacristy crucifix, then lead him out', wrong: ['Genuflect to Father', 'Go ahead to light the candles', 'Kneel for his blessing'], label: 'Bow to the crucifix, lead out' },
      { type: 'do', id: 'e-walk', when: 'The procession to the altar.', q: 'Where do you walk?', a: 'In front of Father, hands joined', wrong: ['Behind Father', 'Beside Father on his right', 'Carrying the missal behind him'], label: 'Walk in front' },
      { type: 'do', id: 'e-biretta', when: 'Arriving at the foot of the altar.', q: 'What do you do first?', a: 'Stand at his right, take the biretta, genuflect with him', wrong: ['Kneel straight away on the Gospel side', 'Go up and open the missal', 'Light the candles'], label: 'Take biretta, genuflect', father: 'Biretta: do you want me to kiss the biretta (and your hand) when taking/giving it?' },
      { type: 'do', id: 'e-hem', when: 'Father goes up the steps carrying the chalice.', q: 'What do you do?', a: 'Lift the front hem of his alb', wrong: ['Follow him up', 'Hold the chalice veil', 'Kneel on the Epistle side'], label: 'Lift alb hem' },
      { type: 'do', id: 'e-sed', when: 'You are holding the biretta.', q: 'Where does it go?', a: 'On the sedilia (bench), Epistle side', wrong: ['On the altar', 'On the credence table', 'You hold it throughout Mass'], zone: 'sedilia', zq: 'Tap where the biretta goes.', label: 'Biretta to sedilia' },
      { type: 'do', id: 'e-kneel', when: 'Father comes down to the foot and genuflects.', q: 'Where do you kneel?', a: 'On the floor at the foot, at Father\'s left (Gospel side)', wrong: ['On the lowest step, Epistle side', 'On the footpace behind him', 'At his right on the Epistle side'], zone: 'footG', zq: 'Tap where you kneel for the prayers at the foot.', label: 'Kneel at Father\'s left at the foot' },
    ] },

  // ───────────────────────────── 2
  { id: 'foot', title: 'Prayers at the foot of the altar', short: 'Foot of altar',
    explain: [
      { title: 'What these prayers are', body: `Before going up to the altar, Father and you pray <b>Psalm 42 (<i>Judica me</i>)</b> back and forth, then each confesses (<b>Confiteor</b>) and asks God's forgiveness. You are kneeling on the floor at his <b>left</b>. This is the longest stretch of Latin you will say — the app splits it into small pieces.<br><br>The theme: <i>"I will go in to the altar of God, to God who gives joy to my youth."</i> Psalm 42 is a priest longing to go up to the altar despite enemies and sadness. Your lines are the replies of hope.` },
      { title: 'The pattern', body: `<table class="mini"><tr><td>Father</td><td><i>In nomine Patris…</i> (both sign) <i>Introibo ad altare Dei.</i></td></tr><tr><td>You</td><td><b>Ad Deum qui laetificat juventutem meam.</b></td></tr><tr><td colspan=2>…four verses of Psalm 42, alternating…</td></tr><tr><td>Father</td><td><i>Gloria Patri…</i> (bow)</td></tr><tr><td>You</td><td><b>Sicut erat…</b></td></tr><tr><td>Father</td><td><i>Introibo…</i> → you again <b>Ad Deum…</b></td></tr><tr><td>Father</td><td><i>Adjutorium nostrum…</i> (sign) → <b>Qui fecit caelum et terram.</b></td></tr><tr><td>Father</td><td>says <b>his</b> Confiteor, bowed</td></tr><tr><td>You</td><td><b>Misereatur tui…</b> → he: Amen</td></tr><tr><td>You</td><td><b>Confiteor…</b> (bowed deeply)</td></tr><tr><td>Father</td><td><i>Misereatur vestri…</i> → <b>Amen</b>; <i>Indulgentiam…</i> (sign) → <b>Amen</b></td></tr><tr><td colspan=2>Four short versicles (bow slightly) → Father goes up.</td></tr></table>` },
      { title: 'Postures during the Confiteor', pic: 'bow', body: `• While <b>Father</b> says his Confiteor: stay kneeling upright.<br>• When he finishes: <b>bow profoundly</b>, turn your head slightly toward him and say <b>Misereatur tui…</b><br>• Then say <b>your Confiteor</b>, still bowed deeply, facing the altar.<br>• At <i>et tibi, Pater</i> and <i>et te, Pater</i>: turn your head a little toward Father.<br>• At <i>mea culpa, mea culpa, mea maxima culpa</i>: strike your breast three times with your right fingertips.<br>• Stay bowed through Father's <i>Misereatur vestri</i> and your <b>Amen</b>; straighten up and <b>sign yourself</b> at <i>Indulgentiam</i>.<br>• Bow slightly from <i>Deus, tu conversus</i> until <i>Oremus</i>.` },
      { title: 'What the Confiteor says', body: `<i>I confess to almighty God, to blessed Mary ever Virgin, to blessed Michael the Archangel, to blessed John the Baptist, to the holy Apostles Peter and Paul, to all the Saints, and to you, Father: that I have sinned exceedingly in thought, word and deed: through my fault, through my fault, through my most grievous fault. Therefore I beseech blessed Mary ever Virgin, blessed Michael… blessed John the Baptist, the holy Apostles Peter and Paul, all the Saints, and you, Father, to pray for me to the Lord our God.</i><br><br>Hook: the list of saints is said <b>twice</b> — first in the "to" form (<i>beatae Mariae… beato Michaeli…</i>), then in the "asking" form (<i>beatam Mariam… beatum Michaelem…</i>). Mary, Michael, John, Peter &amp; Paul, all Saints, you. Same order both times.` },
      { title: 'Going up', map: { hi: ['stepG'] }, body: `After <i>Dominus vobiscum / Et cum spiritu tuo / Oremus</i>, Father goes up the steps: <b>lift the front of his alb</b>, then go to your place: <b>kneeling on the lowest step, Gospel side</b> (the missal is on the Epistle side).` },
    ],
    steps: [
      { type: 'do', id: 'f-sign', when: 'Father begins: "In nomine Patris, et Filii, et Spiritus Sancti. Amen."', q: 'What do you do?', a: 'Sign yourself with him', wrong: ['Bow profoundly', 'Strike your breast', 'Stand up'], label: 'Sign yourself (In nomine Patris)' },
      { type: 'say', id: 'f-ad', cue: 'Introibo ad altare Dei.', cueEn: 'I will go in to the altar of God.', s: 'Ad Deum qui laetificat juventutem meam.', en: 'To God, who gives joy to my youth.', gloss: 'Ad = to · Deum = God · qui = who · laetificat = gladdens · juventutem = youth · meam = my', say: 'ahd DAY-oom kwee lay-TEE-fee-kaht yoo-ven-TOO-tem MAY-ahm' },
      { type: 'say', id: 'f-quia', cue: 'Judica me, Deus, et discerne causam meam de gente non sancta: ab homine iniquo et doloso erue me.', cueEn: 'Judge me, O God, and distinguish my cause from an unholy nation; deliver me from the unjust and deceitful man.', s: 'Quia tu es, Deus, fortitudo mea: quare me repulisti, et quare tristis incedo, dum affligit me inimicus?', en: 'For you, O God, are my strength: why have you cast me off, and why do I go about sad while the enemy afflicts me?', gloss: 'Quia = for · tu es = you are · fortitudo mea = my strength · quare = why · me repulisti = have you rejected me · tristis = sad · incedo = I go · dum = while · affligit = afflicts · inimicus = the enemy', say: 'KWEE-ah too ess DAY-oos, for-tee-TOO-doh MAY-ah: KWAH-ray may ray-POO-lee-stee, et KWAH-ray TREE-stees in-CHAY-doh, doom AHF-flee-jeet may ee-NEE-mee-koos?', hook: 'Strength → why rejected → why sad → while enemy afflicts.' },
      { type: 'say', id: 'f-etin', cue: 'Emitte lucem tuam, et veritatem tuam: ipsa me deduxerunt, et adduxerunt in montem sanctum tuum, et in tabernacula tua.', cueEn: 'Send forth your light and your truth: they have led me and brought me to your holy mountain and into your tabernacles.', s: 'Et introibo ad altare Dei: ad Deum qui laetificat juventutem meam.', en: 'And I will go in to the altar of God: to God who gives joy to my youth.', gloss: 'Et introibo = and I will go in · ad altare Dei = to the altar of God · (then the same as your first line)', say: 'et in-TROH-ee-boh ahd ahl-TAH-ray DAY-ee: ahd DAY-oom kwee lay-TEE-fee-kaht yoo-ven-TOO-tem MAY-ahm', hook: 'It\'s Father\'s first line + your first line, joined with "Et".' },
      { type: 'say', id: 'f-spera', cue: 'Confitebor tibi in cithara, Deus, Deus meus: quare tristis es, anima mea, et quare conturbas me?', cueEn: 'I will praise you on the harp, O God, my God: why are you sad, my soul, and why do you disquiet me?', s: 'Spera in Deo, quoniam adhuc confitebor illi: salutare vultus mei, et Deus meus.', en: 'Hope in God, for I will still give praise to him: the salvation of my countenance, and my God.', gloss: 'Spera = hope · in Deo = in God · quoniam = for · adhuc = still · confitebor illi = I will praise him · salutare = salvation · vultus mei = of my face · et Deus meus = and my God', say: 'SPAY-rah in DAY-oh, KWOH-nee-ahm AHD-ook kon-fee-TAY-bor EEL-lee: sah-loo-TAH-ray VOOL-toos MAY-ee, et DAY-oos MAY-oos', hook: 'Answer to "why are you sad, my soul?" → "Hope in God".' },
      { type: 'do', id: 'f-gpbow', when: 'Father says "Gloria Patri, et Filio, et Spiritui Sancto."', q: 'What do you do?', a: 'Bow your head slightly', wrong: ['Sign yourself', 'Strike your breast', 'Bow profoundly from the waist'], label: 'Bow at Gloria Patri' },
      { type: 'say', id: 'f-sicut', cue: 'Gloria Patri, et Filio, et Spiritui Sancto.', cueEn: 'Glory be to the Father, and to the Son, and to the Holy Spirit.', s: 'Sicut erat in principio, et nunc, et semper: et in saecula saeculorum. Amen.', en: 'As it was in the beginning, is now, and ever shall be, world without end. Amen.', gloss: 'Sicut erat = as it was · in principio = in the beginning · et nunc = and now · et semper = and always · in saecula saeculorum = for ages of ages', say: 'SEE-koot EH-raht in preen-CHEE-pee-oh, et noonk, et SEM-pair: et in SAY-koo-lah say-koo-LOH-room. AH-men' },
      { type: 'say', id: 'f-ad2', alias: 'f-ad', cue: 'Introibo ad altare Dei. (again, after the Gloria Patri)', cueEn: 'I will go in to the altar of God.', s: 'Ad Deum qui laetificat juventutem meam.', en: 'To God, who gives joy to my youth.' },
      { type: 'say', id: 'f-qui', cue: 'Adjutorium nostrum in nomine Domini. (Father signs himself — you too)', cueEn: 'Our help is in the name of the Lord.', s: 'Qui fecit caelum et terram.', en: 'Who made heaven and earth.', gloss: 'Qui = who · fecit = made · caelum = heaven · et terram = and earth', say: 'kwee FAY-cheet CHAY-loom et TEHR-rahm' },
      { type: 'do', id: 'f-pconf', when: 'Father, bowed deeply, says his own Confiteor.', q: 'What do you do while he says it?', a: 'Stay kneeling upright and wait until he finishes', wrong: ['Say it along with him', 'Bow profoundly straight away', 'Strike your breast with him'], label: 'Wait while Father says his Confiteor' },
      { type: 'do', id: 'f-misbow', when: 'Father finishes his Confiteor ("…orare pro me ad Dominum Deum nostrum").', q: 'What do you do?', a: 'Bow profoundly, turn your head a little toward him, and say Misereatur tui…', wrong: ['Say Amen', 'Start your own Confiteor', 'Stand up'], label: 'Bow, turn to Father → Misereatur tui' },
      { type: 'say', id: 'f-mis', cue: '…et vos, fratres, orare pro me ad Dominum Deum nostrum. (end of Father\'s Confiteor)', cueEn: '…and you, brethren, to pray for me to the Lord our God.', s: 'Misereatur tui omnipotens Deus, et dimissis peccatis tuis, perducat te ad vitam aeternam.', en: 'May almighty God have mercy on you, forgive you your sins, and bring you to life everlasting.', gloss: 'Misereatur = may he have mercy · tui = on you · omnipotens Deus = almighty God · dimissis peccatis tuis = your sins having been forgiven · perducat te = may he lead you · ad vitam aeternam = to eternal life', say: 'mee-zeh-ray-AH-toor TOO-ee om-NEE-poh-tens DAY-oos, et dee-MEES-sees pek-KAH-tees TOO-ees, pair-DOO-kaht tay ahd VEE-tahm ay-TAIR-nahm', hook: 'TUI · TUIS · TE — all "you" (singular): you\'re praying for Father.' },
      { type: 'do', id: 'f-cbow', when: 'Father answers "Amen" — now your Confiteor.', q: 'How do you say it?', a: 'Bowed profoundly, facing the altar', wrong: ['Kneeling upright, facing Father', 'Standing, bowed', 'Kneeling, head slightly bowed only'], label: 'Bow deeply for your Confiteor' },
      { type: 'say', id: 'f-c1', cue: '(Father: Amen.) You begin your Confiteor…', cueEn: 'I confess to almighty God, to blessed Mary ever Virgin,', s: 'Confiteor Deo omnipotenti, beatae Mariae semper Virgini,', en: 'I confess to almighty God, to blessed Mary ever Virgin,', say: 'kon-FEE-tay-or DAY-oh om-nee-poh-TEN-tee, bay-AH-tay mah-REE-ay SEM-pair VEER-jee-nee', gloss: 'Confiteor = I confess · Deo omnipotenti = to almighty God · beatae Mariae = to blessed Mary · semper Virgini = ever Virgin' },
      { type: 'say', id: 'f-c2', cue: '…beatae Mariae semper Virgini, (continue)', cueEn: 'to blessed Michael the Archangel, to blessed John the Baptist,', s: 'beato Michaeli Archangelo, beato Joanni Baptistae,', en: 'to blessed Michael the Archangel, to blessed John the Baptist,', say: 'bay-AH-toh mee-kah-AY-lee ark-AHN-jeh-loh, bay-AH-toh yoh-AHN-nee bahp-TEE-stay' },
      { type: 'say', id: 'f-c3', cue: '…beato Joanni Baptistae, (continue — turn toward Father at "et tibi, Pater")', cueEn: 'to the holy Apostles Peter and Paul, to all the Saints, and to you, Father:', s: 'sanctis Apostolis Petro et Paulo, omnibus Sanctis, et tibi, Pater:', en: 'to the holy Apostles Peter and Paul, to all the Saints, and to you, Father:', say: 'SAHNK-tees ah-POH-stoh-lees PAY-troh et POW-loh, OM-nee-boos SAHNK-tees, et TEE-bee, PAH-tair' },
      { type: 'say', id: 'f-c4', cue: '…et tibi, Pater: (continue)', cueEn: 'that I have sinned exceedingly in thought, word and deed:', s: 'quia peccavi nimis cogitatione, verbo et opere:', en: 'that I have sinned exceedingly in thought, word and deed:', say: 'KWEE-ah pek-KAH-vee NEE-mees koh-jee-tah-tsee-OH-nay, VAIR-boh et OH-peh-ray', gloss: 'quia = that · peccavi = I have sinned · nimis = exceedingly · cogitatione = in thought · verbo = word · et opere = and deed' },
      { type: 'do', id: 'f-strike', when: 'At "mea culpa, mea culpa, mea maxima culpa".', q: 'What do you do?', a: 'Strike your breast three times with the fingertips of your right hand', wrong: ['Strike your breast once', 'Bow lower each time', 'Sign yourself'], label: 'Strike breast ×3 at mea culpa' },
      { type: 'say', id: 'f-c5', cue: '…cogitatione, verbo et opere: (continue, striking your breast)', cueEn: 'through my fault, through my fault, through my most grievous fault.', s: 'mea culpa, mea culpa, mea maxima culpa.', en: 'through my fault, through my fault, through my most grievous fault.', say: 'MAY-ah KOOL-pah, MAY-ah KOOL-pah, MAY-ah MAHK-see-mah KOOL-pah' },
      { type: 'say', id: 'f-c6', cue: '…mea maxima culpa. (continue: "Therefore I beseech…")', cueEn: 'Therefore I beseech blessed Mary ever Virgin, blessed Michael the Archangel, blessed John the Baptist,', s: 'Ideo precor beatam Mariam semper Virginem, beatum Michaelem Archangelum, beatum Joannem Baptistam,', en: 'Therefore I beseech blessed Mary ever Virgin, blessed Michael the Archangel, blessed John the Baptist,', say: 'ee-DAY-oh PRAY-kor bay-AH-tahm mah-REE-ahm SEM-pair VEER-jee-nem, bay-AH-toom mee-kah-AY-lem ark-AHN-jeh-loom, bay-AH-toom yoh-AHN-nem bahp-TEE-stahm', hook: 'Same saints as before, now ending in -am / -um / -em.' },
      { type: 'say', id: 'f-c7', cue: '…beatum Joannem Baptistam, (continue — turn toward Father at "et te, Pater")', cueEn: 'the holy Apostles Peter and Paul, all the Saints, and you, Father, to pray for me to the Lord our God.', s: 'sanctos Apostolos Petrum et Paulum, omnes Sanctos, et te, Pater, orare pro me ad Dominum Deum nostrum.', en: 'the holy Apostles Peter and Paul, all the Saints, and you, Father, to pray for me to the Lord our God.', say: 'SAHNK-tohs ah-POH-stoh-lohs PAY-troom et POW-loom, OM-nays SAHNK-tohs, et tay, PAH-tair, oh-RAH-ray proh may ahd DOH-mee-noom DAY-oom NOH-stroom' },
      { type: 'do', id: 'f-turn', when: 'At "et tibi, Pater" and "et te, Pater" (first Confiteor).', q: 'What do you do?', a: 'Turn your head slightly toward Father', wrong: ['Stand up', 'Strike your breast', 'Stay perfectly still facing the altar'], label: 'Turn to Father at "et tibi / et te, Pater"' },
      { type: 'say', id: 'f-amen1', cue: 'Misereatur vestri omnipotens Deus, et dimissis peccatis vestris, perducat vos ad vitam aeternam.', cueEn: 'May almighty God have mercy on you, forgive your sins and bring you to life everlasting.', s: 'Amen.', en: 'Amen.', say: 'AH-men', note: 'Stay bowed for this Amen.' },
      { type: 'do', id: 'f-indsign', when: 'Father: "Indulgentiam, absolutionem et remissionem peccatorum nostrorum…"', q: 'What do you do?', a: 'Straighten up and sign yourself', wrong: ['Stay bowed and strike your breast', 'Stand', 'Turn toward Father'], label: 'Straighten & sign at Indulgentiam' },
      { type: 'say', id: 'f-amen2', alias: 'f-amen1', cue: 'Indulgentiam, absolutionem et remissionem peccatorum nostrorum tribuat nobis omnipotens et misericors Dominus.', cueEn: 'May the almighty and merciful Lord grant us pardon, absolution and remission of our sins.', s: 'Amen.', en: 'Amen.' },
      { type: 'do', id: 'f-slbow', when: 'Father: "Deus, tu conversus…" until "Oremus".', q: 'What do you do?', a: 'Bow slightly during these versicles', wrong: ['Bow profoundly', 'Stand up', 'Sign yourself at each one'], label: 'Bow slightly for the versicles' },
      { type: 'say', id: 'f-plebs', cue: 'Deus, tu conversus vivificabis nos.', cueEn: 'O God, you will turn again and bring us to life.', s: 'Et plebs tua laetabitur in te.', en: 'And your people will rejoice in you.', gloss: 'plebs tua = your people · laetabitur = will rejoice · in te = in you', say: 'et plebs TOO-ah lay-TAH-bee-toor in tay' },
      { type: 'say', id: 'f-sal', cue: 'Ostende nobis, Domine, misericordiam tuam.', cueEn: 'Show us, O Lord, your mercy.', s: 'Et salutare tuum da nobis.', en: 'And grant us your salvation.', gloss: 'salutare tuum = your salvation · da nobis = give us', say: 'et sah-loo-TAH-ray TOO-oom dah NOH-bees' },
      { type: 'say', id: 'f-clam', cue: 'Domine, exaudi orationem meam.', cueEn: 'O Lord, hear my prayer.', s: 'Et clamor meus ad te veniat.', en: 'And let my cry come to you.', gloss: 'clamor meus = my cry · ad te = to you · veniat = may it come', say: 'et KLAH-mor MAY-oos ahd tay VEH-nee-aht' },
      { type: 'say', id: 'dv', cue: 'Dominus vobiscum.', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.', gloss: 'Et = and · cum = with · spiritu tuo = your spirit', say: 'et koom SPEE-ree-too TOO-oh', note: 'You\'ll say this many times in the Mass.' },
      { type: 'do', id: 'f-up', when: 'Father says "Oremus" and goes up the steps.', q: 'What do you do?', a: 'Lift his alb hem, then kneel on the lowest step, Gospel side', wrong: ['Follow him up and kneel on the footpace', 'Go to the credence table', 'Kneel on the Epistle side'], zone: 'stepG', zq: 'Tap where you kneel once Father has gone up.', label: 'Lift alb → kneel lowest step, Gospel side' },
    ],
    wholes: [
      { id: 'w-conf', title: 'The whole Confiteor', of: ['f-c1', 'f-c2', 'f-c3', 'f-c4', 'f-c5', 'f-c6', 'f-c7'] },
      { id: 'w-psalm', title: 'All your Psalm 42 lines', of: ['f-ad', 'f-quia', 'f-etin', 'f-spera', 'f-sicut'], joinCue: true },
    ] },

  // ───────────────────────────── 3
  { id: 'kyrie', title: 'Introit, Kyrie, Gloria & Collect', short: 'Kyrie & Collect',
    explain: [
      { title: 'Introit', map: { hi: ['stepG', 'altarE'] }, body: `Father kisses the altar, goes to the missal on the Epistle side and reads the Introit, <b>signing himself</b> as he begins — <b>you sign yourself too</b>. You stay kneeling on the lowest step, Gospel side.` },
      { title: 'The Kyrie: nine invocations', body: `Father comes to the centre. You alternate, 3 × 3:<table class="mini"><tr><td>Father</td><td>Kyrie, eleison.</td></tr><tr><td>You</td><td><b>Kyrie, eleison.</b></td></tr><tr><td>Father</td><td>Kyrie, eleison.</td></tr><tr><td>You</td><td><b>Christe, eleison.</b></td></tr><tr><td>Father</td><td>Christe, eleison.</td></tr><tr><td>You</td><td><b>Christe, eleison.</b></td></tr><tr><td>Father</td><td>Kyrie, eleison.</td></tr><tr><td>You</td><td><b>Kyrie, eleison.</b></td></tr><tr><td>Father</td><td>Kyrie, eleison. (he has the last one)</td></tr></table>Hook: <b>you switch first</b> — you're the one who says the first <i>Christe</i> and the first of the last group of <i>Kyrie</i>s. Father begins and ends. (It's Greek: "Lord, have mercy / Christ, have mercy". Say KEE-ree-ay eh-LAY-ee-zon.)` },
      { title: 'Gloria & Collect', body: `• <b>Gloria in excelsis</b> (not every day): you say nothing and don't answer Amen. Bow your head at <i>Jesu Christe</i>; sign yourself with Father at the end (<i>cum Sancto Spiritu…</i>).<br>• Father turns: <i>Dominus vobiscum</i> → <b>Et cum spiritu tuo.</b><br>• <i>Oremus</i> (bow head) — the Collect. It ends <i>…per omnia saecula saeculorum.</i> → <b>Amen.</b><br>• If there's a second Collect, answer <b>Amen</b> again after it.` },
    ],
    steps: [
      { type: 'do', id: 'k-intro', when: 'Father begins the Introit at the missal, signing himself.', q: 'What do you do?', a: 'Sign yourself too, still kneeling on the Gospel side', wrong: ['Stand up', 'Go to the Epistle side', 'Nothing'], label: 'Sign yourself at the Introit' },
      { type: 'say', id: 'k1', cue: 'Kyrie, eleison. (Father, 1st)', cueEn: 'Lord, have mercy.', s: 'Kyrie, eleison.', en: 'Lord, have mercy.', say: 'KEE-ree-ay, eh-LAY-ee-zon' },
      { type: 'say', id: 'k2', cue: 'Kyrie, eleison. (Father, 3rd — the last of the first group)', cueEn: 'Lord, have mercy.', s: 'Christe, eleison.', en: 'Christ, have mercy.', say: 'KREE-stay, eh-LAY-ee-zon', hook: 'You start the Christe group.' },
      { type: 'say', id: 'k3', cue: 'Christe, eleison. (Father, 5th)', cueEn: 'Christ, have mercy.', s: 'Christe, eleison.', en: 'Christ, have mercy.', say: 'KREE-stay, eh-LAY-ee-zon' },
      { type: 'say', id: 'k4', cue: 'Kyrie, eleison. (Father, 7th — first of the last group)', cueEn: 'Lord, have mercy.', s: 'Kyrie, eleison.', en: 'Lord, have mercy.', say: 'KEE-ree-ay, eh-LAY-ee-zon', note: 'Father then says the 9th and last.' },
      { type: 'do', id: 'k-gloria', when: 'Father says the Gloria in excelsis.', q: 'What do you do?', a: 'Say nothing; bow at "Jesu Christe"; sign yourself with him at the end', wrong: ['Say it with him', 'Answer Amen at the end', 'Stand for it'], label: 'Gloria: silent, sign at end' },
      { type: 'say', id: 'k-dv', alias: 'dv', cue: 'Dominus vobiscum. (Father turns, before the Collect)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'say', id: 'amen', cue: '…per omnia saecula saeculorum. (end of the Collect)', cueEn: '…for ever and ever.', s: 'Amen.', en: 'Amen.', say: 'AH-men', note: 'Amen after each Collect (sometimes two).' },
    ] },

  // ───────────────────────────── 4
  { id: 'gospel', title: 'Epistle, missal move & Gospel', short: 'Epistle & Gospel',
    explain: [
      { title: 'End of the Epistle', map: { hi: ['altarE'] }, body: `Father reads the Epistle at the Epistle corner. At the end he puts his <b>left hand</b> on the altar (or just stops) → you say <b>Deo gratias</b> ("Thanks be to God").` },
      { title: 'Moving the missal (the big move)', map: { path: ['stepG', 'floorE', 'altarE', 'floorC', 'altarG', 'floorG'] }, body: `1. When Father starts the <b>Gradual / Alleluia</b> (straight after the Epistle), <b>rise</b> and go the <b>long way</b> round to the <b>Epistle side</b>, genuflecting at the centre. Wait on the floor facing Father.<br>2. When he finishes and moves to the centre, go up and <b>take the missal on its stand</b>.<br>3. Carry it <b>straight down to the centre</b>, <b>genuflect</b> (with the book), and <b>straight up</b> to the Gospel side.<br>4. Place it on the Gospel side, <b>angled toward the centre</b> (about 45°).<br>5. Stand on the floor, Gospel side, near the missal, and wait for Father.<br><br>Tip: before Mass, look at how long the Gradual is so you know when to get up.` },
      { title: 'The Gospel', map: { hi: ['floorG', 'floorE'] }, pic: 'crosses', body: `• <i>Dominus vobiscum</i> → <b>Et cum spiritu tuo.</b><br>• <i>Sequentia sancti Evangelii secundum Matthaeum…</i> — with Father make <b>three small crosses with your right thumb on forehead, lips and breast</b> → <b>Gloria tibi, Domine.</b><br>• If <i>Jesus</i> is named in the first line or two, bow, then cross to the <b>Epistle side</b> (genuflect at centre) and <b>stand facing the missal</b>.<br>• At the end Father lifts the book to kiss it → <b>Laus tibi, Christe.</b> Then <b>kneel</b> on the lowest step, Epistle side (opposite the missal).` },
      { title: 'Sermon & Creed', body: `• If there's a <b>sermon</b>, you usually sit (at the sedilia or a server's seat) — ask Father.<br>• <b>Credo</b> (some days): stay kneeling. Bow your head at <i>Jesum Christum</i>; when Father genuflects at <i>Et incarnatus est</i>, bow deeply; sign yourself at the end (<i>et vitam venturi saeculi</i>). No response.` , father: 'If there is a sermon, where should I sit?' },
    ],
    steps: [
      { type: 'say', id: 'deog', cue: '(End of the Epistle — Father lays his left hand on the altar.)', cueEn: '', s: 'Deo gratias.', en: 'Thanks be to God.', say: 'DAY-oh GRAH-tsee-ahs' },
      { type: 'do', id: 'g-rise', when: 'Father begins the Gradual / Alleluia after the Epistle.', q: 'What do you do?', a: 'Rise, go the long way round to the Epistle side (genuflect at centre), wait on the floor facing Father', wrong: ['Stay kneeling until the Gospel', 'Go straight up and take the missal', 'Go to the credence table for the cruets'], zone: 'floorE', zq: 'Tap where you wait for the missal.', label: 'Rise → wait Epistle side, on floor' },
      { type: 'do', id: 'g-take', when: 'Father finishes the Gradual and moves to the centre.', q: 'What do you do?', a: 'Go up and take the missal with its stand', wrong: ['Hand him the chalice veil', 'Ring the bell', 'Wait until he calls you'], zone: 'altarE', zq: 'Tap where you collect the missal.', label: 'Take the missal from the Epistle corner' },
      { type: 'do', id: 'g-carry', when: 'Carrying the missal across.', q: 'Which way?', a: 'Straight down to the centre, genuflect, straight up to the Gospel side', wrong: ['Along the footpace behind Father', 'The long way round the lowest step', 'Down to the floor, bow, then up'], zone: 'floorC', zq: 'Tap where you genuflect with the missal.', label: 'Down to centre, genuflect, up' },
      { type: 'do', id: 'g-place', when: 'Putting the missal down.', q: 'How do you place it?', a: 'On the Gospel side, angled toward the centre (about 45°)', wrong: ['Square to the front edge of the altar', 'In the centre of the altar', 'On the Gospel side, angled outward'], zone: 'altarG', zq: 'Tap where the missal goes for the Gospel.', label: 'Missal on Gospel side, angled in' },
      { type: 'do', id: 'g-wait', when: 'After placing the missal.', q: 'Where do you wait?', a: 'On the floor, Gospel side, near the missal', wrong: ['Kneeling on the Epistle side', 'At the credence table', 'On the footpace beside Father'], zone: 'floorG', zq: 'Tap where you wait for the Gospel.', label: 'Wait on Gospel side' },
      { type: 'say', id: 'g-dv', alias: 'dv', cue: 'Dominus vobiscum. (before the Gospel)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'do', id: 'g-cross', when: 'Father: "Sequentia sancti Evangelii secundum…" (and makes three small crosses).', q: 'What do you do?', a: 'Make three small crosses with your thumb — forehead, lips, breast', wrong: ['One large sign of the cross', 'Bow profoundly', 'Genuflect'], label: 'Three small crosses' },
      { type: 'say', id: 'gtd', cue: 'Sequentia sancti Evangelii secundum Matthaeum. (or Marcum, Lucam, Joannem)', cueEn: 'The continuation of the holy Gospel according to Matthew.', s: 'Gloria tibi, Domine.', en: 'Glory to you, O Lord.', say: 'GLOH-ree-ah TEE-bee, DOH-mee-nay' },
      { type: 'do', id: 'g-cross2', when: 'Straight after "Gloria tibi, Domine".', q: 'What do you do?', a: 'Bow if Jesus is named early, then cross to the Epistle side (genuflect at centre) and stand facing the missal', wrong: ['Kneel where you are on the Gospel side', 'Go to the credence table', 'Stand behind Father'], zone: 'floorE', zq: 'Tap where you stand for the rest of the Gospel.', label: 'Cross to Epistle side, stand' },
      { type: 'say', id: 'laus', cue: '(End of the Gospel — Father lifts the book to kiss it.)', cueEn: '', s: 'Laus tibi, Christe.', en: 'Praise to you, O Christ.', say: 'lowss TEE-bee, KREE-stay', hook: 'GLORIA at the start, LAUS at the end — G before L.' },
      { type: 'do', id: 'g-kneel', when: 'After "Laus tibi, Christe".', q: 'What do you do?', a: 'Kneel on the lowest step, Epistle side', wrong: ['Kneel on the Gospel side', 'Go to the credence table', 'Stay standing until the Offertory'], zone: 'stepE', zq: 'Tap where you kneel after the Gospel.', label: 'Kneel, lowest step, Epistle side' },
      { type: 'do', id: 'g-credo', when: 'The Credo, at "Et incarnatus est" (Father genuflects).', q: 'What do you do?', a: 'Bow deeply (you are already kneeling)', wrong: ['Stand', 'Ring the bell', 'Strike your breast'], label: 'Credo: bow at Et incarnatus' },
    ] },

  // ───────────────────────────── 5
  { id: 'offer', title: 'Offertory, cruets & Lavabo', short: 'Offertory',
    explain: [
      { title: 'Start of the Offertory', map: { hi: ['altarE'] }, body: `Father: <i>Dominus vobiscum</i> → <b>Et cum spiritu tuo</b>. <i>Oremus.</i> Then <b>rise</b>, go up the Epistle side and <b>take the chalice veil</b> from Father. Fold it in three (cross showing, if it has one) and lay it at the Epistle end of the altar.`, father: 'Chalice veil: where do you want it folded and placed during the Offertory?' },
      { title: 'The cruets — how to hold them', pic: 'cruetsOffer', map: { hi: ['credence', 'altarE'] }, body: `At the credence table: <b>wine in your right hand, water in your left</b>. Hold each by the <b>body</b>, with the <b>handles turned toward Father</b> so he can take them by the handle.<br><br>Wait at the Epistle corner (on the top step at the edge of the footpace). When Father turns to you, give a <b>low bow of the head</b>.<br><br><b>Wine first:</b> kiss the wine cruet, hand it to him. Move the water cruet to your <b>right</b> hand. Take the wine cruet back in your <b>left</b>. Father <b>blesses the water</b> (sign of the cross over it) — hold it still; then kiss it and hand it to him. Take it back in your right hand. Bow, kiss the cruets again and put them back on the credence.`, father: 'Cruets: do you want them kissed (before giving and after receiving)?' },
      { title: 'Memory hook: R-W, L-W', body: `<b>R</b>ight hand = <b>W</b>ine (Red), <b>L</b>eft = water. <b>Wine goes first.</b> Handles <b>toward Father</b> at the Offertory because <b>he takes them</b>.<br>At the Ablutions later it's the opposite: <b>you pour</b>, so you hold them <b>by the handle yourself</b>.` },
      { title: 'The Lavabo (hand washing)', pic: 'lavabo', body: `Back at the credence: unfold the <b>finger towel</b> and lay it over your <b>left forearm</b> (if it has a cross, let Father see it). Take the <b>water cruet in your right hand</b> and the <b>dish in your left</b>.<br>Go to the Epistle corner, bow when Father turns to you. <b>Pour slowly over his fingertips</b> into the dish until he signals stop (he may lift his fingers). He dries his hands on the towel on your arm. Bow, go back.<br>Then bring the <b>bell</b> and kneel on the lowest step, Epistle side.` },
      { title: 'Orate fratres → Suscipiat', body: `Father turns: <i>Orate, fratres…</i> ("Pray, brethren, that my sacrifice and yours may be acceptable to God the Father almighty"). He turns back to the altar and you answer — the second-longest response of the Mass:<br><br><b>Suscipiat Dominus sacrificium de manibus tuis,<br>ad laudem et gloriam nominis sui,<br>ad utilitatem quoque nostram, totiusque Ecclesiae suae sanctae.</b><br><br><i>May the Lord receive the sacrifice from your hands, to the praise and glory of his name, for our good also, and that of all his holy Church.</i><br><br>Hook: <b>receive → praise &amp; glory → our good → whole Church</b> (God, then us, then everyone).` },
    ],
    steps: [
      { type: 'say', id: 'o-dv', alias: 'dv', cue: 'Dominus vobiscum. (before the Offertory)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'do', id: 'o-veil', when: 'Father says "Oremus" and begins the Offertory.', q: 'What do you do?', a: 'Rise, go up the Epistle side, take the chalice veil, fold it and lay it at the Epistle end', wrong: ['Bring the cruets straight away', 'Ring the bell once', 'Move the missal back'], zone: 'altarE', zq: 'Tap where you go for the chalice veil.', label: 'Take & fold the chalice veil', father: 'Chalice veil: where do you want it folded and placed during the Offertory?' },
      { type: 'do', id: 'o-hold', when: 'Picking up the cruets at the credence table.', q: 'How do you hold them?', a: 'Wine in right hand, water in left, by the body, handles toward Father', wrong: ['Water in right, wine in left, handles toward Father', 'Wine in right, water in left, holding them by the handles', 'Both in one hand on the tray'], pic: 'cruetsOffer', label: 'Wine R, water L, handles to Father' },
      { type: 'do', id: 'o-wait', when: 'You have the cruets.', q: 'Where do you wait?', a: 'At the Epistle corner, at the edge of the footpace', wrong: ['At the centre in front of the tabernacle', 'On the Gospel side', 'At the credence table until called'], zone: 'altarE', zq: 'Tap where you present the cruets.', label: 'Wait at Epistle corner' },
      { type: 'do', id: 'o-first', when: 'Father turns to you for the cruets.', q: 'What do you do?', a: 'Bow your head, kiss the wine cruet and hand it over (wine first)', wrong: ['Hand him the water first', 'Hand both at once', 'Pour the wine into the chalice yourself'], label: 'Bow, wine first', father: 'Cruets: do you want them kissed (before giving and after receiving)?' },
      { type: 'do', id: 'o-swap', when: 'Father has taken the wine cruet.', q: 'What next?', a: 'Move the water to your right hand; take the wine back in your left', wrong: ['Hand the water with your left hand', 'Go back to the credence', 'Kneel'], label: 'Water to right hand, wine back in left' },
      { type: 'do', id: 'o-bless', when: 'Before Father takes the water.', q: 'What happens?', a: 'He blesses the water — hold it still, then hand it to him', wrong: ['He blesses the wine', 'He asks you to pour it', 'Nothing, just hand it over'], label: 'Father blesses the water' },
      { type: 'do', id: 'o-back', when: 'Father returns the water cruet.', q: 'What do you do?', a: 'Take it in your right hand, bow, (kiss the cruets) and return them to the credence', wrong: ['Leave them on the altar', 'Kneel straight away', 'Hand him the towel'], label: 'Bow, return cruets' },
      { type: 'do', id: 'o-lavset', when: 'Preparing the Lavabo.', q: 'How do you carry things?', a: 'Towel over left forearm, water cruet in right hand, dish in left', wrong: ['Towel over right forearm, dish in right hand', 'Dish and cruet on the towel', 'Towel in your left hand, cruet in the dish'], pic: 'lavabo', label: 'Towel L arm, water R, dish L' },
      { type: 'do', id: 'o-pour', when: 'At the Lavabo, Father holds his fingers over the dish.', q: 'What do you do?', a: 'Pour slowly over his fingertips until he signals to stop; he dries them on the towel', wrong: ['Pour the whole cruet quickly', 'Pour onto his palms', 'Hand him the cruet to pour himself'], label: 'Pour over fingertips until signal' },
      { type: 'do', id: 'o-bell', when: 'Lavabo finished, things back on the credence.', q: 'What do you do?', a: 'Take the bell and kneel on the lowest step, Epistle side', wrong: ['Kneel on the Gospel side', 'Go up to the footpace with the bell', 'Leave the bell and kneel'], zone: 'stepE', zq: 'Tap where you kneel for the rest of the Offertory.', label: 'Bell → kneel, lowest step Epistle side' },
      { type: 'say', id: 'o-s1', cue: 'Orate, fratres: ut meum ac vestrum sacrificium acceptabile fiat apud Deum Patrem omnipotentem. (once Father has turned back)', cueEn: 'Pray, brethren, that my sacrifice and yours may be acceptable to God the Father almighty.', s: 'Suscipiat Dominus sacrificium de manibus tuis,', en: 'May the Lord receive the sacrifice from your hands,', gloss: 'Suscipiat = may he receive · Dominus = the Lord · sacrificium = the sacrifice · de manibus tuis = from your hands', say: 'soo-SHEE-pee-aht DOH-mee-noos sah-kree-FEE-chee-oom day MAH-nee-boos TOO-ees' },
      { type: 'say', id: 'o-s2', cue: '…de manibus tuis, (continue)', cueEn: 'to the praise and glory of his name,', s: 'ad laudem et gloriam nominis sui,', en: 'to the praise and glory of his name,', gloss: 'ad laudem = to the praise · et gloriam = and glory · nominis sui = of his name', say: 'ahd LOW-dem et GLOH-ree-ahm NOH-mee-nees SOO-ee' },
      { type: 'say', id: 'o-s3', cue: '…nominis sui, (continue)', cueEn: 'for our good also, and that of all his holy Church.', s: 'ad utilitatem quoque nostram, totiusque Ecclesiae suae sanctae.', en: 'for our good also, and that of all his holy Church.', gloss: 'ad utilitatem = for the benefit · quoque = also · nostram = our · totiusque = and of the whole · Ecclesiae suae sanctae = of his holy Church', say: 'ahd oo-tee-lee-TAH-tem KWOH-kway NOH-strahm, toh-tsee-OOS-kway ek-KLAY-zee-ay SOO-ay SAHNK-tay' },
    ],
    wholes: [{ id: 'w-susc', title: 'The whole Suscipiat', of: ['o-s1', 'o-s2', 'o-s3'] }] },

  // ───────────────────────────── 6
  { id: 'pref', title: 'Preface dialogue & Sanctus', short: 'Preface',
    explain: [
      { title: 'The Preface dialogue', body: `Father ends the Secret prayers aloud: <i>…Per omnia saecula saeculorum.</i> → <b>Amen.</b><br><table class="mini"><tr><td>Dominus vobiscum.</td><td><b>Et cum spiritu tuo.</b></td></tr><tr><td>Sursum corda. <small>(Lift up your hearts)</small></td><td><b>Habemus ad Dominum.</b> <small>(We have them lifted up to the Lord)</small></td></tr><tr><td>Gratias agamus Domino Deo nostro. <small>(Let us give thanks to the Lord our God)</small></td><td><b>Dignum et justum est.</b> <small>(It is right and just)</small></td></tr></table>Hook: <b>A–E–H–D</b>: <b>A</b>men, <b>E</b>t cum, <b>H</b>abemus, <b>D</b>ignum. Hearts up → "we have them"; give thanks → "it's right".` },
      { title: 'Sanctus bell', pic: 'bell', body: `Father says the Preface, then bows: <i>Sanctus, Sanctus, Sanctus…</i> → <b>ring the bell three times</b> (once for each <i>Sanctus</i>, or three short rings).<br>At <i>Benedictus qui venit</i> Father signs himself — <b>sign yourself</b> too.`, father: 'Sanctus bell: one ring per "Sanctus", or one continuous ring?' },
    ],
    steps: [
      { type: 'say', id: 'p-amen', alias: 'amen', cue: '…Per omnia saecula saeculorum. (end of the Secret)', cueEn: '…for ever and ever.', s: 'Amen.', en: 'Amen.' },
      { type: 'say', id: 'p-dv', alias: 'dv', cue: 'Dominus vobiscum. (Preface)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'say', id: 'hab', cue: 'Sursum corda.', cueEn: 'Lift up your hearts.', s: 'Habemus ad Dominum.', en: 'We have lifted them up to the Lord.', gloss: 'Habemus = we have (them) · ad Dominum = to the Lord', say: 'ah-BAY-moos ahd DOH-mee-noom' },
      { type: 'say', id: 'dig', cue: 'Gratias agamus Domino Deo nostro.', cueEn: 'Let us give thanks to the Lord our God.', s: 'Dignum et justum est.', en: 'It is right and just.', gloss: 'Dignum = worthy/right · et justum = and just · est = it is', say: 'DEE-nyoom et YOO-stoom est' },
      { type: 'do', id: 'p-sanc', when: 'Father bows and says "Sanctus, Sanctus, Sanctus…".', q: 'What do you do?', a: 'Ring the bell three times', wrong: ['Ring once', 'Ring continuously until the Benedictus', 'Say the Sanctus with him'], label: 'Sanctus: ring ×3', father: 'Sanctus bell: one ring per "Sanctus", or one continuous ring?' },
      { type: 'do', id: 'p-ben', when: '"Benedictus qui venit…" (Father signs himself).', q: 'What do you do?', a: 'Sign yourself', wrong: ['Ring the bell', 'Strike your breast', 'Stand up'], label: 'Sign at Benedictus' },
    ] },

  // ───────────────────────────── 7
  { id: 'canon', title: 'The Canon & Consecration', short: 'Consecration',
    explain: [
      { title: 'Hanc igitur — the warning bell', map: { hi: ['stepE'], path: ['stepE', 'foot'] }, body: `The Canon is said silently. Watch Father. When he <b>spreads his hands over the chalice</b> (<i>Hanc igitur</i>) → <b>ring the bell once</b>: a warning that the Consecration is near.<br>When he takes his hands away, <b>rise with the bell</b>, go toward the centre and <b>up to the footpace</b>; kneel on the top step <b>a little behind Father, to his right</b> (no genuflection on the way up). Bell beside you on the step.`, father: 'Hanc igitur: do you want the warning bell, and do I come up to the footpace for the Consecration?' },
      { title: 'The two elevations', pic: 'chasuble', body: `<b>Consecration of the Host:</b><br>• Father genuflects → <b>1 ring</b><br>• He elevates the Host → <b>lift the back hem of the chasuble slightly with your left hand</b> and <b>ring 3 times</b> with your right<br>• He genuflects again → <b>1 ring</b><br><br><b>Consecration of the Chalice:</b> exactly the same — 1, lift + 3, 1.<br><br>Hook: <b>1–3–1, twice.</b> Look up at the Host and the Chalice when they're raised (you can say inwardly "My Lord and my God").`, father: 'Elevations: bells 1–3–1 (genuflection, elevation, genuflection), or just 3 at each elevation?' },
      { title: 'After the Consecration', map: { path: ['foot', 'floorC', 'stepE'] }, body: `Take the bell, come down to the centre, <b>genuflect</b>, and go back to kneel on the <b>lowest step, Epistle side</b>.<br><br>The Canon ends aloud: <i>…Per omnia saecula saeculorum.</i> → <b>Amen.</b><br><i>Oremus. Praeceptis salutaribus…</i> Father says the <b>Pater noster</b> alone. He ends <i>…Et ne nos inducas in tentationem.</i> → you finish: <b>Sed libera nos a malo.</b> ("But deliver us from evil")<br>Then <i>…Per omnia saecula saeculorum.</i> → <b>Amen.</b> <i>Pax Domini sit semper vobiscum.</i> → <b>Et cum spiritu tuo.</b>` },
    ],
    steps: [
      { type: 'do', id: 'c-hanc', when: 'Father spreads his hands over the chalice (Hanc igitur).', q: 'What do you do?', a: 'Ring the bell once', wrong: ['Ring three times', 'Go up to the footpace straight away', 'Strike your breast'], label: 'Hanc igitur: ring once', father: 'Hanc igitur: do you want the warning bell, and do I come up to the footpace for the Consecration?' },
      { type: 'do', id: 'c-up', when: 'Father takes his hands from over the chalice.', q: 'What do you do?', a: 'Rise with the bell and kneel on the footpace, a little behind Father to his right', wrong: ['Stay on the lowest step', 'Go to the Gospel side', 'Genuflect at the centre and kneel on the floor'], zone: 'foot', zq: 'Tap where you kneel for the Consecration.', label: 'Up to footpace, kneel at Father\'s right' },
      { type: 'do', id: 'c-host', when: 'Consecration of the Host.', q: 'How do you ring?', a: '1 at his genuflection, 3 at the elevation, 1 at his second genuflection', wrong: ['3 at the elevation only, nothing else', '1 at the elevation', 'Continuously from genuflection to genuflection'], label: 'Host: bells 1–3–1', father: 'Elevations: bells 1–3–1 (genuflection, elevation, genuflection), or just 3 at each elevation?' },
      { type: 'do', id: 'c-chas', when: 'Father elevates the Host (and later the Chalice).', q: 'What do you do with your left hand?', a: 'Lift the back hem of the chasuble slightly', wrong: ['Hold the front of his alb', 'Strike your breast', 'Hold the bell'], pic: 'chasuble', label: 'Lift chasuble at elevations' },
      { type: 'do', id: 'c-chal', when: 'Consecration of the Chalice.', q: 'What do you do?', a: 'The same again: 1, lift chasuble + 3, 1', wrong: ['Nothing — the bells are only for the Host', 'One ring only', 'Go back down after the Host'], label: 'Chalice: same again 1–3–1' },
      { type: 'do', id: 'c-down', when: 'After the Consecration of the Chalice.', q: 'What do you do?', a: 'Take the bell, go down to the centre, genuflect, kneel on the lowest step, Epistle side', wrong: ['Stay on the footpace until Communion', 'Go to the Gospel side', 'Return the bell to the credence and sit'], zone: 'stepE', zq: 'Tap where you go back to after the Consecration.', label: 'Down, genuflect, lowest step Epistle side' },
      { type: 'say', id: 'c-amen', alias: 'amen', cue: '…Per omnia saecula saeculorum. (end of the Canon, said aloud)', cueEn: '…for ever and ever.', s: 'Amen.', en: 'Amen.' },
      { type: 'say', id: 'sed', cue: '…Et ne nos inducas in tentationem.', cueEn: '…And lead us not into temptation.', s: 'Sed libera nos a malo.', en: 'But deliver us from evil.', gloss: 'Sed = but · libera = deliver · nos = us · a malo = from evil', say: 'sed LEE-beh-rah nohs ah MAH-loh', hook: 'Father says the whole Our Father; you only say the last line.' },
      { type: 'say', id: 'c-amen2', alias: 'amen', cue: '…Per omnia saecula saeculorum. (after the Libera nos)', cueEn: '…for ever and ever.', s: 'Amen.', en: 'Amen.' },
      { type: 'say', id: 'c-pax', alias: 'dv', cue: 'Pax Domini sit semper vobiscum.', cueEn: 'The peace of the Lord be always with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
    ] },

  // ───────────────────────────── 8
  { id: 'comm', title: 'Agnus Dei & Communion', short: 'Communion',
    explain: [
      { title: 'Agnus Dei & Domine non sum dignus', pic: 'bell', body: `• <b>Agnus Dei</b>: Father strikes his breast at <i>miserere nobis</i> (×2) and <i>dona nobis pacem</i> — <b>strike yours with him</b>.<br>• Father's Communion: he says <i>Domine, non sum dignus…</i> three times, striking his breast → <b>ring the bell once each time</b> (as he says <i>dignus</i>).` },
      { title: 'Your Confiteor again + the paten', map: { path: ['stepE', 'credence', 'floorC', 'foot'] }, body: `When Father has received the Precious Blood: put the bell back, take the <b>Communion paten</b> from the credence, go to the centre, <b>genuflect</b>, go up and <b>kneel on the footpace at Father's right</b>.<br>Immediately <b>bow profoundly</b> and say the <b>Confiteor</b> again — the same words as at the start, but <b>this time don't turn toward Father</b> at <i>et tibi / et te, Pater</i>.<br>Father: <i>Misereatur vestri…</i> → <b>Amen.</b> <i>Indulgentiam…</i> (sign) → <b>Amen.</b>` },
      { title: 'Ecce Agnus Dei & receiving', body: `Father turns with the Host: <i>Ecce Agnus Dei…</i> then <i>Domine, non sum dignus…</i> three times. The people (and you) may say it with him, striking the breast:<br><b>Domine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanabitur anima mea.</b><br><i>Lord, I am not worthy that you should enter under my roof: but only say the word and my soul shall be healed.</i><br><br>You receive first, kneeling, on the tongue. Father says <i>Corpus Domini nostri Jesu Christi custodiat animam tuam in vitam aeternam. Amen.</i> — <b>he</b> says the Amen; <b>you say nothing</b>.` , father: 'Domine non sum dignus at the people\'s Communion: should I say it aloud with the people?' },
      { title: 'The paten at the rail', pic: 'paten', map: { hi: ['rail'] }, body: `Stand, go with Father to the <b>communion rail</b>, on his <b>right</b>. Hold the paten <b>flat by its handle</b> just <b>under each communicant's chin</b>, moving along with Father. Keep it level and steady — it's there to catch any particle.<br>(If you are not receiving, a common signal is a finger to your lips.)<br>Afterwards return with Father; he'll purify the paten. Kneel on the lowest step, Epistle side, until the tabernacle is closed.`, father: 'After Communion: do I hand you the paten at the altar, or leave it on the altar for you?' },
    ],
    steps: [
      { type: 'do', id: 'm-agnus', when: 'Agnus Dei (Father strikes his breast).', q: 'What do you do?', a: 'Strike your breast with him (three times)', wrong: ['Ring the bell three times', 'Sign yourself', 'Nothing'], label: 'Agnus Dei: strike breast' },
      { type: 'do', id: 'm-dnsd', when: 'Father says "Domine, non sum dignus…" three times before his Communion.', q: 'What do you do?', a: 'Ring the bell once each time, at "dignus"', wrong: ['Ring three times at the first one only', 'Ring continuously', 'Say it with him, no bell'], label: 'Domine non sum dignus: ring ×1 each time' },
      { type: 'do', id: 'm-paten', when: 'Father has received the Precious Blood.', q: 'What do you do?', a: 'Return the bell, take the paten, genuflect at centre, kneel on the footpace at Father\'s right', wrong: ['Go and get the cruets', 'Move the missal', 'Stay where you are'], zone: 'foot', zq: 'Tap where you kneel with the paten.', label: 'Get paten → kneel footpace, Father\'s right' },
      { type: 'say', id: 'm-conf', alias: 'w-conf', cue: '(Kneeling on the footpace, bowed profoundly — begin the Confiteor straight away.)', cueEn: 'The second Confiteor.', s: '', en: 'The whole Confiteor again.', note: 'Don\'t turn toward Father this time.' },
      { type: 'do', id: 'm-noturn', when: 'Second Confiteor, at "et tibi, Pater".', q: 'What is different this time?', a: 'You don\'t turn toward Father', wrong: ['You stand', 'You don\'t strike your breast', 'You say it kneeling upright'], label: 'No turning in 2nd Confiteor' },
      { type: 'say', id: 'm-am1', alias: 'f-amen1', cue: 'Misereatur vestri omnipotens Deus… perducat vos ad vitam aeternam.', cueEn: 'May almighty God have mercy on you…', s: 'Amen.', en: 'Amen.' },
      { type: 'say', id: 'm-am2', alias: 'f-amen1', cue: 'Indulgentiam, absolutionem et remissionem peccatorum vestrorum… (sign yourself)', cueEn: 'May the almighty and merciful Lord grant you pardon…', s: 'Amen.', en: 'Amen.' },
      { type: 'say', id: 'dnsd', cue: 'Ecce Agnus Dei, ecce qui tollit peccata mundi. (then, with the people, three times:)', cueEn: 'Behold the Lamb of God, behold him who takes away the sins of the world.', s: 'Domine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanabitur anima mea.', en: 'Lord, I am not worthy that you should enter under my roof: but only say the word and my soul shall be healed.', gloss: 'non sum dignus = I am not worthy · ut intres = that you enter · sub tectum meum = under my roof · sed tantum = but only · dic verbo = say the word · sanabitur = will be healed · anima mea = my soul', say: 'DOH-mee-nay, non soom DEE-nyoos, oot IN-trays soob TEK-toom MAY-oom: sed TAHN-toom deek VAIR-boh, et sah-NAH-bee-toor AH-nee-mah MAY-ah', father: 'Domine non sum dignus at the people\'s Communion: should I say it aloud with the people?' },
      { type: 'do', id: 'm-recv', when: 'Father gives you Communion: "Corpus Domini nostri Jesu Christi custodiat animam tuam in vitam aeternam. Amen."', q: 'What do you say?', a: 'Nothing — Father says the Amen; receive on the tongue', wrong: ['Amen', 'Deo gratias', 'Et cum spiritu tuo'], label: 'Receive — say nothing' },
      { type: 'do', id: 'm-rail', when: 'Communion of the people.', q: 'What do you do?', a: 'Go with Father on his right; hold the paten flat under each person\'s chin', wrong: ['Hold the paten against each person\'s chest', 'Walk ahead of Father', 'Stay kneeling on the footpace'], zone: 'rail', zq: 'Tap where you hold the paten for the people.', pic: 'paten', label: 'Paten under chins at the rail' },
      { type: 'do', id: 'm-after', when: 'Communion of the people finished, Father returns to the altar.', q: 'What do you do?', a: 'Return with him, leave the paten with Father, genuflect, kneel on the lowest step, Epistle side until the tabernacle is closed', wrong: ['Go straight to move the missal', 'Put the paten on the credence and sit', 'Kneel on the Gospel side'], label: 'Paten to Father, kneel Epistle side', father: 'After Communion: do I hand you the paten at the altar, or leave it on the altar for you?' },
    ] },

  // ───────────────────────────── 9
  { id: 'ablu', title: 'Ablutions & missal back', short: 'Ablutions',
    explain: [
      { title: 'The cruets the other way round', pic: 'cruetsAblu', body: `When the tabernacle is closed, rise, take the <b>wine and water cruets</b> from the credence and wait at the Epistle corner. This time <b>you pour</b>, so hold each <b>by its handle</b> yourself (wine in right hand, water in left).<br><br>Contrast: <b>Offertory = handles toward Father</b> (he takes them). <b>Ablutions = handles toward you</b> (you pour).` },
      { title: 'Two ablutions', map: { hi: ['altarE'] }, body: `<b>1. Purifying the chalice:</b> Father holds the chalice toward you (often at the centre or tips it toward you). Go up and <b>pour wine</b> into it until he raises the chalice / signals.<br><b>2. Purifying his fingers:</b> He comes to the Epistle corner and holds his fingers over the chalice. <b>Bow</b>, pour <b>a little wine</b> over his fingers, then <b>water</b>, following his signals.<br>Bow, put the cruets back. Come back (no bow needed) and take the <b>paten</b> from the altar to the credence.`, father: 'Ablutions: how much wine for the first, and at the fingers wine then water — any signal you use?' },
      { title: 'Missal back to the Epistle side', map: { path: ['floorC', 'stepG', 'altarG', 'floorC', 'altarE', 'stepG'] }, body: `1. Go to the centre, genuflect, the <b>long way</b> round to the Gospel side (you're empty-handed).<br>2. Take the <b>missal</b>, go <b>straight down to the centre, genuflect</b>, up to the <b>Epistle side</b>; place it <b>square</b> (straight, facing out) for the Communion antiphon.<br>3. Help Father with the <b>chalice veil and burse</b> if he wants it (hold the burse while he puts the corporal in, hand him the veil, then the burse).<br>4. Kneel on the <b>lowest step, Gospel side</b> (missal is now on the Epistle side).`, father: 'After the ablutions: do you want me to bring the chalice veil / help with the burse?' },
    ],
    steps: [
      { type: 'do', id: 'a-get', when: 'The tabernacle is closed after Communion.', q: 'What do you do?', a: 'Rise, take wine and water from the credence, wait at the Epistle corner', wrong: ['Move the missal first', 'Take the lavabo dish and towel', 'Stay kneeling until the Blessing'], zone: 'credence', zq: 'Tap where you go first.', label: 'Get cruets, wait at Epistle corner' },
      { type: 'do', id: 'a-hold', when: 'Holding the cruets for the ablutions.', q: 'How do you hold them?', a: 'By the handles yourself — you are pouring', wrong: ['By the body, handles toward Father', 'Both in your right hand', 'On the lavabo dish'], pic: 'cruetsAblu', label: 'Ablutions: hold by the handles' },
      { type: 'do', id: 'a-first', when: 'First ablution: Father holds the chalice toward you.', q: 'What do you pour?', a: 'Wine into the chalice, until he signals', wrong: ['Water into the chalice', 'Wine and water together', 'Water over his fingers'], label: '1st ablution: wine into chalice' },
      { type: 'do', id: 'a-second', when: 'Second ablution: Father holds his fingers over the chalice.', q: 'What do you pour?', a: 'A little wine, then water, over his fingers', wrong: ['Water, then wine', 'Water only', 'Wine only'], label: '2nd ablution: wine then water over fingers' },
      { type: 'do', id: 'a-paten', when: 'Cruets returned to the credence.', q: 'What next?', a: 'Go back and take the paten from the altar to the credence', wrong: ['Kneel straight away', 'Take the chalice', 'Ring the bell'], label: 'Paten to credence' },
      { type: 'do', id: 'a-missal', when: 'Moving the missal back.', q: 'How?', a: 'Long way to the Gospel side; take the missal; down to the centre, genuflect; up to the Epistle side', wrong: ['Carry it along the footpace behind Father', 'Leave it — Father moves it', 'Long way round in both directions'], label: 'Missal back to Epistle side' },
      { type: 'do', id: 'a-kneel', when: 'Missal is back on the Epistle side, chalice veiled.', q: 'Where do you kneel?', a: 'Lowest step, Gospel side', wrong: ['Lowest step, Epistle side', 'On the footpace', 'At the sedilia'], zone: 'stepG', zq: 'Tap where you kneel for the end of Mass.', label: 'Kneel, lowest step, Gospel side' },
    ] },

  // ───────────────────────────── 10
  { id: 'end', title: 'Blessing, Last Gospel & leaving', short: 'Conclusion',
    explain: [
      { title: 'The final responses', body: `<table class="mini"><tr><td>Dominus vobiscum.</td><td><b>Et cum spiritu tuo.</b></td></tr><tr><td>Postcommunion … per omnia saecula saeculorum.</td><td><b>Amen.</b></td></tr><tr><td>Dominus vobiscum.</td><td><b>Et cum spiritu tuo.</b></td></tr><tr><td>Ite, missa est. <small>(or Benedicamus Domino)</small></td><td><b>Deo gratias.</b></td></tr><tr><td>Benedicat vos omnipotens Deus, Pater, et Filius, et Spiritus Sanctus.</td><td><b>Amen.</b> (kneel, sign yourself)</td></tr></table>` },
      { title: 'The Last Gospel', map: { hi: ['stepG', 'floorE'] }, body: `Stand after the Blessing. Father goes to the Gospel side (to the altar card).<br>• <i>Dominus vobiscum</i> → <b>Et cum spiritu tuo.</b><br>• <i>Initium sancti Evangelii secundum Joannem.</i> — three small crosses → <b>Gloria tibi, Domine.</b><br>• Cross to the <b>Epistle side</b> (genuflect at centre) and stand facing the altar.<br>• At <i>Et Verbum caro factum est</i> → <b>genuflect</b> with Father.<br>• At the end (<i>…plenum gratiae et veritatis</i>) → <b>Deo gratias.</b>` },
      { title: 'Leaving', body: `Father comes down to the foot. If the <b>Leonine prayers</b> are said, kneel beside him and pray them (they're in Extras).<br>Then get the <b>biretta</b> from the sedilia, <b>genuflect</b> with Father at the foot, hand him the biretta, and <b>lead him out</b>. In the sacristy, <b>bow to the crucifix</b> with him; he may say <i>Prosit</i> (see Extras). Afterwards: extinguish the candles (Gospel side first), tidy the cruets.` },
    ],
    steps: [
      { type: 'say', id: 'x-dv', alias: 'dv', cue: 'Dominus vobiscum. (before the Postcommunion)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'say', id: 'x-amen', alias: 'amen', cue: '…per omnia saecula saeculorum. (end of the Postcommunion)', cueEn: '…for ever and ever.', s: 'Amen.', en: 'Amen.' },
      { type: 'say', id: 'x-dv2', alias: 'dv', cue: 'Dominus vobiscum. (before Ite, missa est)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'say', id: 'ite', cue: 'Ite, missa est. (or: Benedicamus Domino.)', cueEn: 'Go, it is the dismissal.', s: 'Deo gratias.', en: 'Thanks be to God.', alias: 'deog' },
      { type: 'do', id: 'x-bless', when: 'Father blesses: "Benedicat vos omnipotens Deus…".', q: 'What do you do?', a: 'Kneeling, sign yourself and answer Amen', wrong: ['Stand and bow', 'Say Deo gratias', 'Strike your breast'], label: 'Blessing: kneel, sign' },
      { type: 'say', id: 'x-bamen', alias: 'amen', cue: 'Benedicat vos omnipotens Deus, Pater, et Filius, et Spiritus Sanctus.', cueEn: 'May almighty God bless you, the Father, the Son and the Holy Spirit.', s: 'Amen.', en: 'Amen.' },
      { type: 'do', id: 'x-stand', when: 'After the Blessing.', q: 'What do you do?', a: 'Stand for the Last Gospel', wrong: ['Stay kneeling', 'Go for the biretta', 'Move the missal'], label: 'Stand for Last Gospel' },
      { type: 'say', id: 'x-dv3', alias: 'dv', cue: 'Dominus vobiscum. (Last Gospel)', cueEn: 'The Lord be with you.', s: 'Et cum spiritu tuo.', en: 'And with your spirit.' },
      { type: 'say', id: 'x-gtd', alias: 'gtd', cue: 'Initium sancti Evangelii secundum Joannem.', cueEn: 'The beginning of the holy Gospel according to John.', s: 'Gloria tibi, Domine.', en: 'Glory to you, O Lord.' },
      { type: 'do', id: 'x-cross', when: 'After "Gloria tibi, Domine" at the Last Gospel.', q: 'Where do you go?', a: 'Cross to the Epistle side (genuflect at centre) and stand', wrong: ['Stay on the Gospel side', 'Kneel at the foot', 'Go to the sedilia'], zone: 'floorE', zq: 'Tap where you stand for the Last Gospel.', label: 'Cross to Epistle side, stand' },
      { type: 'do', id: 'x-verbum', when: '"Et Verbum caro factum est" in the Last Gospel.', q: 'What do you do?', a: 'Genuflect with Father', wrong: ['Bow your head', 'Sign yourself', 'Ring the bell'], label: 'Genuflect at Verbum caro factum est' },
      { type: 'say', id: 'x-deog', alias: 'deog', cue: '…plenum gratiae et veritatis. (end of the Last Gospel)', cueEn: '…full of grace and truth.', s: 'Deo gratias.', en: 'Thanks be to God.' },
      { type: 'do', id: 'x-leave', when: 'After the Last Gospel (and any prayers at the foot).', q: 'What do you do?', a: 'Get the biretta, genuflect with Father, hand him the biretta, lead him out', wrong: ['Leave first without waiting', 'Extinguish the candles first', 'Wait for Father to leave, then follow'], label: 'Biretta, genuflect, lead out' },
      { type: 'do', id: 'x-sacr', when: 'Back in the sacristy.', q: 'What do you do?', a: 'Bow to the crucifix with Father', wrong: ['Genuflect to Father', 'Leave straight away', 'Say Ite missa est'], label: 'Bow to the sacristy crucifix' },
    ] },
  ];

  // ───────────────────────────── EXTRAS (don't count toward progress)
  const extras = [
  { id: 'xsac', optional: true, title: 'Sacristy, candles & versicles', short: 'Sacristy & candles',
    explain: [
      { title: 'Candles', map: { hi: ['altarE', 'altarG'] }, body: `Only <b>two candles</b> are lit for a Low Mass.<br>• <b>Lighting</b>: Epistle side first, then Gospel side (if more than one each side, start with the one nearest the cross).<br>• <b>Extinguishing</b>: the reverse — Gospel side first, then Epistle side.<br>Hook: <b>"Epistle lights first, Gospel lights out first."</b>` },
      { title: 'Helping Father vest', body: `Make sure the alb is unfolded at the bottom, hand him the cincture, and hold up the back of the chasuble while he ties its ribbons. The priest's vesting prayers are his own — you don't answer them.` },
      { title: 'Versicles in the sacristy', body: `Before Mass, after bowing to the crucifix, Father may say one of:<br>• <i>Procedamus in pace.</i> → <b>In nomine Christi. Amen.</b><br>• <i>Adjutorium nostrum in nomine Domini.</i> → <b>Qui fecit caelum et terram.</b><br><br>After Mass, some priests say <i>Prosit</i> → <b>Pro omnibus et singulis.</b> ("May it profit" → "For each and every one"). The server may then kneel and ask a blessing: <b>Jube, domne, benedicere.</b>`, father: 'Sacristy: do you use "Procedamus in pace" / "Prosit", and do you give the server a blessing after Mass?' },
    ],
    steps: [
      { type: 'do', id: 'xs-light', when: 'Lighting the candles before Mass.', q: 'Which first?', a: 'Epistle side first, then Gospel side', wrong: ['Gospel side first', 'Whichever is nearest the sacristy', 'Both at once'], label: 'Light: Epistle first' },
      { type: 'do', id: 'xs-out', when: 'Extinguishing after Mass.', q: 'Which first?', a: 'Gospel side first, then Epistle side', wrong: ['Epistle side first', 'Either', 'The one nearest the cross'], label: 'Extinguish: Gospel first' },
      { type: 'do', id: 'xs-num', when: 'Low Mass.', q: 'How many candles?', a: 'Two', wrong: ['Four', 'Six', 'One'], label: 'Two candles' },
      { type: 'say', id: 'xs-proc', cue: 'Procedamus in pace.', cueEn: 'Let us go forth in peace.', s: 'In nomine Christi. Amen.', en: 'In the name of Christ. Amen.', say: 'in NOH-mee-nay KREE-stee. AH-men' },
      { type: 'say', id: 'xs-prosit', cue: 'Prosit.', cueEn: 'May it profit (you).', s: 'Pro omnibus et singulis.', en: 'For each and every one.', say: 'proh OM-nee-boos et SEEN-goo-lees' },
      { type: 'say', id: 'xs-jube', cue: '(You kneel to ask Father\'s blessing.)', cueEn: '', s: 'Jube, domne, benedicere.', en: 'Pray, sir, a blessing.', say: 'YOO-bay, DOM-nay, beh-neh-DEE-cheh-ray' },
    ] },
  { id: 'xleo', optional: true, title: 'Leonine prayers after Low Mass', short: 'Leonine prayers',
    explain: [
      { title: 'What they are', body: `After Low Mass, kneeling at the foot, Father may lead the "Leonine prayers": <b>three Hail Marys, the Salve Regina, a versicle and prayer, the prayer to St Michael</b>, and often <b>"Most Sacred Heart of Jesus — have mercy on us" ×3</b>. They are often said in English or in the local language; if in Latin, you and the people say the second half of each prayer. Learn these only if you have time — they're not required of the server.`, father: 'Prayers after Low Mass: do you say them, and in Latin or English?' },
      { title: 'Ave Maria — second half', body: `Father: <i>Ave Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Jesus.</i><br>All: <b>Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostrae. Amen.</b>` },
    ],
    steps: [
      { type: 'say', id: 'xl-ave', cue: 'Ave Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Jesus.', cueEn: 'Hail Mary, full of grace…', s: 'Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostrae. Amen.', en: 'Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.', say: 'SAHNK-tah mah-REE-ah, MAH-tair DAY-ee, OH-rah proh NOH-bees pek-kah-toh-REE-boos, noonk et in OH-rah MOR-tees NOH-stray. AH-men' },
      { type: 'say', id: 'xl-s1', cue: 'Salve Regina (said together) —', cueEn: 'Hail, holy Queen, Mother of mercy, our life, our sweetness and our hope, hail.', s: 'Salve, Regina, Mater misericordiae, vita, dulcedo et spes nostra, salve.', en: 'Hail, holy Queen, Mother of mercy, our life, our sweetness and our hope, hail.' },
      { type: 'say', id: 'xl-s2', cue: '…spes nostra, salve. (continue)', cueEn: 'To you we cry, poor banished children of Eve.', s: 'Ad te clamamus, exsules filii Hevae.', en: 'To you we cry, poor banished children of Eve.' },
      { type: 'say', id: 'xl-s3', cue: '…exsules filii Hevae. (continue)', cueEn: 'To you we send up our sighs, mourning and weeping in this valley of tears.', s: 'Ad te suspiramus, gementes et flentes in hac lacrimarum valle.', en: 'To you we send up our sighs, mourning and weeping in this valley of tears.' },
      { type: 'say', id: 'xl-s4', cue: '…in hac lacrimarum valle. (continue)', cueEn: 'Turn then, our advocate, your eyes of mercy toward us.', s: 'Eia ergo, advocata nostra, illos tuos misericordes oculos ad nos converte.', en: 'Turn then, most gracious advocate, your eyes of mercy toward us.' },
      { type: 'say', id: 'xl-s5', cue: '…oculos ad nos converte. (continue)', cueEn: 'And after this exile show us Jesus, the blessed fruit of your womb.', s: 'Et Jesum, benedictum fructum ventris tui, nobis post hoc exsilium ostende.', en: 'And after this our exile, show us the blessed fruit of your womb, Jesus.' },
      { type: 'say', id: 'xl-s6', cue: '…post hoc exsilium ostende. (continue)', cueEn: 'O clement, O loving, O sweet Virgin Mary.', s: 'O clemens, O pia, O dulcis Virgo Maria.', en: 'O clement, O loving, O sweet Virgin Mary.' },
      { type: 'say', id: 'xl-ora', cue: 'Ora pro nobis, sancta Dei Genetrix.', cueEn: 'Pray for us, O holy Mother of God.', s: 'Ut digni efficiamur promissionibus Christi.', en: 'That we may be made worthy of the promises of Christ.' },
      { type: 'say', id: 'xl-m1', cue: 'Sancte Michael Archangele (said together) —', cueEn: 'Holy Michael Archangel, defend us in battle; be our protection against the wickedness and snares of the devil.', s: 'Sancte Michael Archangele, defende nos in praelio; contra nequitiam et insidias diaboli esto praesidium.', en: 'Holy Michael Archangel, defend us in battle; be our protection against the wickedness and snares of the devil.' },
      { type: 'say', id: 'xl-m2', cue: '…esto praesidium. (continue)', cueEn: 'May God rebuke him, we humbly pray:', s: 'Imperet illi Deus, supplices deprecamur:', en: 'May God rebuke him, we humbly pray:' },
      { type: 'say', id: 'xl-m3', cue: '…supplices deprecamur: (continue)', cueEn: 'and do you, Prince of the heavenly host, by the power of God, thrust into hell Satan and the other evil spirits who prowl about the world seeking the ruin of souls. Amen.', s: 'tuque, Princeps militiae caelestis, Satanam aliosque spiritus malignos, qui ad perditionem animarum pervagantur in mundo, divina virtute in infernum detrude. Amen.', en: 'and do you, Prince of the heavenly host, by the power of God thrust into hell Satan and the other evil spirits who wander through the world for the ruin of souls. Amen.' },
      { type: 'say', id: 'xl-cor', cue: 'Cor Jesu sacratissimum. (×3)', cueEn: 'Most Sacred Heart of Jesus.', s: 'Miserere nobis.', en: 'Have mercy on us.', say: 'mee-zeh-REH-ray NOH-bees' },
    ],
    wholes: [{ id: 'w-salve', title: 'The whole Salve Regina', of: ['xl-s1', 'xl-s2', 'xl-s3', 'xl-s4', 'xl-s5', 'xl-s6'] }, { id: 'w-mich', title: 'The whole St Michael prayer', of: ['xl-m1', 'xl-m2', 'xl-m3'] }] },
  ];

  return { Z, sections, extras };
})();
